import re
from typing import List, Tuple

def compare_versions(a: str, b: str) -> int:
    version_regex = re.compile(r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$')

    def _parse_version(version: str) -> Tuple[int, int, int, List[str]]:
        match = version_regex.match(version)
        if not match:
            raise ValueError(f"Invalid version string: {version}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease = match.group(4).split('.') if match.group(4) else []

        return major, minor, patch, prerelease

    major_a, minor_a, patch_a, prerelease_a = _parse_version(a)
    major_b, minor_b, patch_b, prerelease_b = _parse_version(b)

    if (major_a, minor_a, patch_a) < (major_b, minor_b, patch_b):
        return -1
    if (major_a, minor_a, patch_a) > (major_b, minor_b, patch_b):
        return 1

    # If MAJOR, MINOR, PATCH are equal, compare pre-release versions
    if prerelease_a and not prerelease_b:
        return -1
    if not prerelease_a and prerelease_b:
        return 1

    # Compare pre-release identifiers
    for id_a, id_b in zip(prerelease_a, prerelease_b):
        if id_a.isdigit() and id_b.isdigit():
            if int(id_a) < int(id_b):
                return -1
            if int(id_a) > int(id_b):
                return 1
        elif id_a.isdigit():
            return -1  # numeric < alphanumeric
        elif id_b.isdigit():
            return 1  # alphanumeric > numeric
        else:
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1

    # If all shared identifiers are equal, the longer list wins
    if len(prerelease_a) < len(prerelease_b):
        return -1
    if len(prerelease_a) > len(prerelease_b):
        return 1

    return 0

import re
from typing import List, Tuple

def compare_versions(a: str, b: str) -> int:
    version_a = _parse_version(a)
    version_b = _parse_version(b)

    # Compare major, minor, patch
    for va, vb in zip(version_a[:3], version_b[:3]):
        if va < vb:
            return -1
        elif va > vb:
            return 1

    # If major, minor, patch are equal, compare pre-release
    if len(version_a) == 4 and len(version_b) == 3:
        return -1  # a has pre-release, b does not
    elif len(version_a) == 3 and len(version_b) == 4:
        return 1  # b has pre-release, a does not
    elif len(version_a) == 4 and len(version_b) == 4:
        return _compare_prerelease(version_a[3], version_b[3])

    return 0  # They are equal

def _parse_version(version: str) -> List:
    # Regex to match the version format
    version_regex = re.compile(r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$')
    match = version_regex.match(version)

    if not match:
        raise ValueError(f"Invalid version string: {version}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = match.group(4)

    # Convert prerelease into a list of identifiers if it exists
    if prerelease:
        prerelease_parts = _split_prerelease(prerelease)
        return [major, minor, patch, prerelease_parts]

    return [major, minor, patch]

def _split_prerelease(prerelease: str) -> List:
    parts = prerelease.split('.')
    return [ _convert_identifier(part) for part in parts ]

def _convert_identifier(identifier: str):
    # Convert numeric identifiers to int for comparison
    if identifier.isdigit():
        return (0, int(identifier))  # Numeric identifiers have lower precedence
    return (1, identifier)  # Alphanumeric identifiers have higher precedence

def _compare_prerelease(prerelease_a: List, prerelease_b: List) -> int:
    for part_a, part_b in zip(prerelease_a, prerelease_b):
        if part_a < part_b:
            return -1
        elif part_a > part_b:
            return 1

    # If all shared identifiers are equal, the longer list wins
    if len(prerelease_a) < len(prerelease_b):
        return -1
    elif len(prerelease_a) > len(prerelease_b):
        return 1

    return 0  # They are equal

