import pytest
from solution import compare_versions


def test_example_equal_versions():
    assert compare_versions('1.0.0', '1.0.0') == 0, f"got {compare_versions('1.0.0', '1.0.0')!r}"

def test_example_major_version_a_less():
    assert compare_versions('1.0.0', '2.0.0') == -1, f"got {compare_versions('1.0.0', '2.0.0')!r}"

def test_example_major_version_a_greater():
    assert compare_versions('2.0.0', '1.0.0') == 1, f"got {compare_versions('2.0.0', '1.0.0')!r}"

def test_example_minor_version_a_less():
    assert compare_versions('1.1.0', '1.2.0') == -1, f"got {compare_versions('1.1.0', '1.2.0')!r}"

def test_example_minor_version_a_greater():
    assert compare_versions('1.2.0', '1.1.0') == 1, f"got {compare_versions('1.2.0', '1.1.0')!r}"

def test_example_patch_version_a_less():
    assert compare_versions('1.0.1', '1.0.2') == -1, f"got {compare_versions('1.0.1', '1.0.2')!r}"

def test_example_patch_version_a_greater():
    assert compare_versions('1.0.2', '1.0.1') == 1, f"got {compare_versions('1.0.2', '1.0.1')!r}"

def test_example_pre_release_lower_precedence():
    assert compare_versions('1.0.0-alpha', '1.0.0') == -1, f"got {compare_versions('1.0.0-alpha', '1.0.0')!r}"

def test_example_pre_release_higher_precedence():
    assert compare_versions('1.0.0', '1.0.0-alpha') == 1, f"got {compare_versions('1.0.0', '1.0.0-alpha')!r}"

def test_example_invalid_version():
    with pytest.raises(ValueError):
        compare_versions('1.0.0.0', '1.0.0')
    with pytest.raises(ValueError):
        compare_versions('1.0.0-alpha.01', '1.0.0-alpha.1')
    with pytest.raises(ValueError):
        compare_versions('1.0.0-alpha+', '1.0.0')

from hypothesis import given, strategies as st

@st.composite
def valid_version(draw):
    major = draw(st.integers(min_value=0, max_value=9))
    minor = draw(st.integers(min_value=0, max_value=9))
    patch = draw(st.integers(min_value=0, max_value=9))
    return f'{major}.{minor}.{patch}'

@given(valid_version(), valid_version())
def test_property_version_comparison(a, b):
    if a == b:
        assert compare_versions(a, b) == 0, f"got {compare_versions(a, b)!r}"
    elif a < b:
        assert compare_versions(a, b) == -1, f"got {compare_versions(a, b)!r}"
    else:
        assert compare_versions(a, b) == 1, f"got {compare_versions(a, b)!r}"

@given(valid_version())
def test_property_invalid_version(a):
    with pytest.raises(ValueError):
        compare_versions(a + 'invalid', '1.0.0')
    with pytest.raises(ValueError):
        compare_versions(a + '.1', '1.0.0')
    with pytest.raises(ValueError):
        compare_versions(a + '-alpha.01', '1.0.0')
    with pytest.raises(ValueError):
        compare_versions(a + '+build', '1.0.0')

