_VERSION_PATTERN = re.compile(
    r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)'
    r'(?:-([\da-zA-Z]+(?:\.[\da-zA-Z]+)*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str) -> List:
        match = _VERSION_PATTERN.match(version)
        if not match:
            raise ValueError(f"Invalid version: {version}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        pre_release = match.group(4)

        if pre_release:
            pre_release_parts = pre_release.split('.')
            pre_release_parts = [
                (int(part) if part.isdigit() else part) for part in pre_release_parts
            ]
        else:
            pre_release_parts = []

        return (major, minor, patch, pre_release_parts)

    ver_a = parse_version(a)
    ver_b = parse_version(b)

    # Compare major, minor, and patch
    if ver_a[0] != ver_b[0]:
        return (ver_a[0] > ver_b[0]) - (ver_a[0] < ver_b[0])
    if ver_a[1] != ver_b[1]:
        return (ver_a[1] > ver_b[1]) - (ver_a[1] < ver_b[1])
    if ver_a[2] != ver_b[2]:
        return (ver_a[2] > ver_b[2]) - (ver_a[2] < ver_b[2])

    # Compare pre-release versions
    if ver_a[3] and not ver_b[3]:
        return -1  # a has pre-release, b does not
    if not ver_a[3] and ver_b[3]:
        return 1   # b has pre-release, a does not

    # Compare pre-release identifiers
    for part_a, part_b in zip(ver_a[3], ver_b[3]):
        if isinstance(part_a, int) and isinstance(part_b, int):
            if part_a != part_b:
                return (part_a > part_b) - (part_a < part_b)
        elif isinstance(part_a, int):  # numeric < alphanumeric
