    got = parse_csv_line('')
    assert got == [''], f'got {got!r}'

def test_example_single_field():
    got = parse_csv_line('field')
    assert got == ['field'], f'got {got!r}'

def test_example_multiple_fields():
    got = parse_csv_line('field1,field2,field3')
    assert got == ['field1', 'field2', 'field3'], f'got {got!r}'

def test_example_quoted_field():
    got = parse_csv_line('"quoted field"')
    assert got == ['quoted field'], f'got {got!r}'

def test_example_quoted_field_with_comma():
    got = parse_csv_line('"field with, comma"')
    assert got == ['field with, comma'], f'got {got!r}'

def test_example_escaped_quote():
    got = parse_csv_line('"field with a double quote: """')
    assert got == ['field with a double quote: "'], f'got {got!r}'

def test_example_trailing_comma():
    got = parse_csv_line('field1,field2,')
    assert got == ['field1', 'field2', ''], f'got {got!r}'

def test_example_unterminated_quoted_field():
    with pytest.raises(ValueError):
        parse_csv_line('"unterminated field')

