import re

def evaluate(expr: str) -> float:
    expr = expr.replace(' ', '')  # Remove whitespace

    if not expr:
        raise ValueError("Empty expression")

    if not _is_valid_expression(expr):
        raise ValueError("Malformed expression")

    return _evaluate_expression(expr)

def _is_valid_expression(expr: str) -> bool:
    # A regex pattern to validate the expression
    token_pattern = r"""
        ^                           # Start of expression
        (?:                         # Non-capturing group for the whole expression
            (?:                    # Non-capturing group for numbers or parentheses
                \d+(?:\.\d+)?     # Matches a number (integer or decimal)
                |                  # or
                \(\s*             # Matches an open parenthesis with optional spaces
                    (?:           # Non-capturing group for inner expression
                        [^\(\)]+   # Matches anything that is not a parenthesis
                        |
                        (?:\s*)   # Allows for empty space
                    )*            # Zero or more times
                \)                # Matches a closing parenthesis
            )
            (?:                    # Non-capturing group for operators
                [+\-*/**]         # Matches any operator
                (?:              # Non-capturing group for the next number or parenthesis
                    \d+(?:\.\d+)? # Matches a number (integer or decimal)
                    |            # or
                    \(\s*        # Matches an open parenthesis with optional spaces
                        (?:      # Non-capturing group for inner expression
                            [^\(\)]+
                            |
                            (?:\s*)
                        )*
                    \)
                )
            )*                    # Zero or more operators followed by numbers/parentheses
        )                           # End of expression
        $                           # End of expression
    """

    return re.match(token_pattern, expr, re.VERBOSE) is not None

def _evaluate_expression(expr: str) -> float:
    tokens = _tokenize(expr)
    return _parse_expression(tokens)

def _tokenize(expr: str):
    # A simple tokenizer for the expression
    token_pattern = r'\d+\.\d+|\d+|[()+\-*/**]'
    return re.findall(token_pattern, expr)

def _parse_expression(tokens):
    def parse(tokens):
        stack = []
        current_number = None
        current_op = None

        while tokens:
            token = tokens.pop(0)

            if re.match(r'\d+(\.\d+)?', token):
                number = float(token)
                if current_op:
                    if current_op == '+':
                        current_number += number
                    elif current_op == '-':
                        current_number -= number
                    elif current_op == '*':
                        current_number *= number
                    elif current_op == '/':
                        if number == 0:
                            raise ZeroDivisionError("Division by zero")
