def test_example_expression_with_power():
    assert evaluate('2 ** 3') == 8.0, f"got {evaluate('2 ** 3')!r}"

def test_example_expression_with_unary_minus():
    assert evaluate('-2 + 3') == 1.0, f"got {evaluate('-2 + 3')!r}"

def test_example_division_by_zero():
    with pytest.raises(ZeroDivisionError):
        evaluate('1 / 0')

def test_example_malformed_input_empty():
    with pytest.raises(ValueError):
        evaluate('')

def test_example_malformed_input_unbalanced_parentheses():
    with pytest.raises(ValueError):
        evaluate('(1 + 2')

def test_example_malformed_input_dangling_operator():
    with pytest.raises(ValueError):
        evaluate('1 + * 2')

def test_example_malformed_input_two_numbers_in_a_row():
    with pytest.raises(ValueError):
        evaluate('1 2 + 3')

