def from_roman(s: str) -> int:
    if not s or not s.isupper() or any(c not in "IVXLCDM" for c in s):
        raise ValueError("Invalid Roman numeral")

    roman_numerals = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0
    count = 0

    for i, char in enumerate(s):
        value = roman_numerals[char]

        # Check for invalid repetitions
        if char in "VLD" and count > 0:
            raise ValueError("Invalid Roman numeral")
        if char in "IXC" and (i > 0 and s[i] == s[i - 1]):
            count += 1
            if count > 3:
                raise ValueError("Invalid Roman numeral")
        else:
            count = 1

        # Check for subtractive combinations
        if value > prev_value:
            total += value - 2 * prev_value  # Subtract the previous value twice
        else:
            total += value

        prev_value = value

    if total < 1 or total > 3999:
        raise ValueError("Invalid Roman numeral")

    return total

