def from_roman(s: str) -> int:
    if not s or any(c not in 'IVXLCDM' for c in s) or any(s.count(c) > 3 for c in 'IXC'):
        raise ValueError("Invalid Roman numeral")

    roman_to_int = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_to_int[char]

        if value < prev_value:
            total -= value
