    # Validate the structure of the Roman numeral
    if not _is_valid_roman(s):
        raise ValueError("Invalid Roman numeral")

    return total

def _is_valid_roman(s: str) -> bool:
    # Check for invalid sequences
    if 'IIII' in s or 'VV' in s or 'XXXX' in s or 'LL' in s or 'CCCC' in s or 'DD' in s or 'MMMM' in s:
        return False
    if 'IL' in s or 'IC' in s or 'ID' in s or 'IM' in s:
        return False
    if 'VX' in s or 'VL' in s or 'VC' in s or 'VD' in s or 'VM' in s:
