def flatten(obj: dict) -> dict:
    result = {}
    _recurse(obj, result)
    return result

def _recurse(current, result, path=''):
    if isinstance(current, dict):
        if not current:  # Handle empty dict
            result[path] = {}
        for k, v in current.items():
            new_path = f"{path}.{k}" if path else k
            _recurse(v, result, new_path)
    elif isinstance(current, list):
        if not current:  # Handle empty list
            result[path] = []
        for i, v in enumerate(current):
            new_path = f"{path}.{i}" if path else str(i)
            _recurse(v, result, new_path)
    else:
        result[path] = current

    # Remove the empty dict entry if the path is empty
    if path == '' and isinstance(current, dict) and not current:
        del result[path]

def flatten(obj: dict) -> dict:
    def _flatten(current, parent_key=''):
        if isinstance(current, dict):
            if not current and parent_key:  # Check for empty dict
                result[parent_key] = {}
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key)
        elif isinstance(current, list):
            if not current and parent_key:  # Check for empty list
                result[parent_key] = []
            for i, v in enumerate(current):
                new_key = f"{parent_key}.{i}" if parent_key else str(i)
                _flatten(v, new_key)
        else:
            result[parent_key] = current

