def flatten_oracle(obj):
    result = {}
    def recurse(current, path):
        if isinstance(current, dict):
            for k, v in current.items():
                recurse(v, path + [k])
        elif isinstance(current, list):
            for i, v in enumerate(current):
                recurse(v, path + [str(i)])
        else:
            result['.'.join(path)] = current
    recurse(obj, [])
    return result

