import pytest
from solution import to_base, from_base
from hypothesis import given, strategies as st


def test_example_zero_to_base():
    assert to_base(0, 10) == '0', f"got {to_base(0, 10)!r}"

def test_example_positive_to_base():
    assert to_base(10, 2) == '1010', f"got {to_base(10, 2)!r}"

def test_example_negative_to_base():
    assert to_base(-10, 16) == '-a', f"got {to_base(-10, 16)!r}"

def test_example_large_to_base():
    assert to_base(255, 16) == 'ff', f"got {to_base(255, 16)!r}"

def test_example_invalid_base_to_base():
    with pytest.raises(ValueError):
        to_base(10, 1)
    with pytest.raises(ValueError):
        to_base(10, 37)

def test_example_valid_from_base():
    assert from_base('1010', 2) == 10, f"got {from_base('1010', 2)!r}"
    assert from_base('-a', 16) == -10, f"got {from_base('-a', 16)!r}"
    assert from_base('ff', 16) == 255, f"got {from_base('ff', 16)!r}"

def test_example_invalid_from_base():
    with pytest.raises(ValueError):
        from_base('10a', 10)
    with pytest.raises(ValueError):
        from_base('g', 16)
    with pytest.raises(ValueError):
        from_base(' 10', 10)
    with pytest.raises(ValueError):
        from_base('+10', 10)
    with pytest.raises(ValueError):
        from_base('10_10', 10)

def test_property_to_base_from_base():
    @given(st.integers(min_value=-1000, max_value=1000), st.integers(min_value=2, max_value=36))
    def test_round_trip(n, base):
        if n == 0:
            assert from_base(to_base(n, base), base) == n, f"got {from_base(to_base(n, base), base)!r}"
        else:
            assert from_base(to_base(n, base), base) == n, f"got {from_base(to_base(n, base), base)!r}"


