    if not s:  # If the string is just a negative sign
        raise ValueError("Invalid string for the given base.")

    value = 0
    for char in s:
        if char.isdigit():
            digit = int(char)
        else:
            digit = ord(char) - ord('a') + 10

        if digit >= base:
            raise ValueError("Invalid digit for the given base.")

        value = value * base + digit

    return -value if negative else value

