import heapq
from collections import defaultdict, deque

def topo_order(deps: dict[str, list[str]]) -> list[str]:
    in_degree = defaultdict(int)
    graph = defaultdict(list)

    # Build the graph and in-degree count
    for task, prerequisites in deps.items():
        for prereq in prerequisites:
            graph[prereq].append(task)
            in_degree[task] += 1
        # Ensure every task is in in_degree even if it has no prerequisites
        if task not in in_degree:
            in_degree[task] = 0

    # Min-heap for tasks with no prerequisites (in-degree of 0)
    min_heap = []
    for task, degree in in_degree.items():
        if degree == 0:
            heapq.heappush(min_heap, task)

    order = []

    while min_heap:
        current = heapq.heappop(min_heap)
        order.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(min_heap, neighbor)

    # Check if the order contains all tasks
    if len(order) != len(in_degree):
        raise ValueError("Cycle detected in the tasks.")

    return order

