from typing import List, Dict

def topo_order(deps: Dict[str, List[str]]) -> List[str]:
    visited = {}
    result = []

    def _visit(task: str):
        if task in visited:
            if visited[task] == 1:
                raise ValueError("Cycle detected")
            return
        visited[task] = 1  # Mark as visiting
        for dep in sorted(deps.get(task, [])):
            _visit(dep)
        visited[task] = 2  # Mark as visited
        result.append(task)

    all_tasks = set(deps.keys())
    for task_list in deps.values():
        all_tasks.update(task_list)

    for task in sorted(all_tasks):
        if task not in visited:
            _visit(task)

    return result[::-1]

