def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string is not a valid duration.")

    pattern = r'^(?:(\d+)([dhms]))*$'
    matches = re.findall(r'(\d+)([dhms])', s)

    if len(matches) == 0 or len(s) != sum(len(m[0]) + 1 for m in matches):
        raise ValueError("Invalid duration format.")

    total_seconds = 0
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    last_unit_index = -1

    for number, unit in matches:
        if unit not in units:
            raise ValueError("Invalid unit found.")

        current_unit_index = 'dhms'.index(unit)
        if current_unit_index <= last_unit_index:
            raise ValueError("Units must appear in the order d, h, m, s.")

        total_seconds += int(number) * units[unit]
        last_unit_index = current_unit_index

    return total_seconds

