import pytest
from solution import rle_encode, rle_decode
from hypothesis import given, strategies as st


def test_example_empty():
    assert rle_encode('') == '', 'Expected empty string to encode to empty string'


def test_example_single_character():
    assert rle_encode('a') == '1a', 'Expected single character to encode to 1 followed by the character'


def test_example_multiple_characters():
    assert rle_encode('aaab') == '3a1b', 'Expected three a's followed by one b'


def test_example_long_run():
    assert rle_encode('zzzzzzzzzzzz') == '9z3z', 'Expected twelve z's to be encoded as 9z3z'


def test_example_mixed_characters():
    assert rle_encode('112233') == '211223', 'Expected mixed digits to be encoded correctly'


def test_example_decoding():
    assert rle_decode('3a1b') == 'aaab', 'Expected decoding to return the original string'


def test_example_invalid_length():
    with pytest.raises(ValueError):
        rle_decode('3a1')  # Odd length


def test_example_invalid_digit():
    with pytest.raises(ValueError):
        rle_decode('0a')  # Invalid digit


def test_property_round_trip():
    @given(st.text())
    def check_round_trip(s):
        assert rle_decode(rle_encode(s)) == s, f'Failed for {s!r}'
    check_round_trip()


def test_property_length_invariant():
    @given(st.text())
    def check_length_invariant(s):
        encoded = rle_encode(s)
        assert len(encoded) <= len(s) * 2, f'Encoded length {len(encoded)} exceeds expected for {s!r}'
    check_length_invariant()


def test_property_character_invariant():
    @given(st.text())
    def check_character_invariant(s):
        encoded = rle_encode(s)
        for i in range(0, len(encoded), 2):
            count = encoded[i]
            char = encoded[i + 1]
            assert count.isdigit() and '1' <= count <= '9', f'Invalid count {count!r} in {encoded!r}'
    check_character_invariant()

